import { readFile } from "node:fs/promises";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import {
	loadTopology,
	releaseConsumers,
	workspaceById,
	workspaceByName,
} from "./repository-control-plane.mjs";

const execFileAsync = promisify(execFile);
const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const sinceIndex = process.argv.indexOf("--since");
const since = sinceIndex >= 0 ? process.argv[sinceIndex + 1] : "origin/main";

if (!since) throw new Error("Missing value for --since");

const topology = loadTopology(root);
const releaseTriggerFiles = new Map(
	topology.release.triggers.map((trigger) => [
		trigger.path,
		workspaceById(topology, trigger.workspace).name,
	]),
);
const releaseBumps = new Set(["patch", "minor", "major"]);

const { stdout } = await execFileAsync(
	"git",
	["diff", "--name-only", "--diff-filter=ACMRD", `${since}...HEAD`],
	{ cwd: root },
);
const changedFiles = stdout.trim().split("\n").filter(Boolean);

async function readPackageName(packagePath) {
	const manifestPath = `${packagePath}/package.json`;
	let contents;

	try {
		contents = await readFile(resolve(root, manifestPath), "utf8");
	} catch {
		try {
			const result = await execFileAsync(
				"git",
				["show", `${since}:${manifestPath}`],
				{ cwd: root },
			);
			contents = result.stdout;
		} catch {
			return undefined;
		}
	}

	try {
		const packageJson = JSON.parse(contents);
		return typeof packageJson.name === "string" ? packageJson.name : undefined;
	} catch {
		return undefined;
	}
}

const changedPackagePaths = new Set();
for (const file of changedFiles) {
	const match = file.match(/^packages\/([^/]+)(?:\/|$)/);
	if (match) changedPackagePaths.add(`packages/${match[1]}`);
}

const changedPackages = new Map();
for (const path of changedPackagePaths) {
	const packageName = await readPackageName(path);
	if (packageName) changedPackages.set(path, packageName);
}
for (const file of changedFiles) {
	const packageName = releaseTriggerFiles.get(file);
	if (packageName) changedPackages.set(file, packageName);
}

if (changedPackages.size === 0) {
	console.log("No workspace package changes require a package changeset.");
	process.exit(0);
}

const { stdout: changesetDiff } = await execFileAsync(
	"git",
	[
		"diff",
		"--name-status",
		"--find-renames",
		`${since}...HEAD`,
		"--",
		".changeset",
	],
	{ cwd: root },
);
const changedChangesetFiles = changesetDiff
	.trim()
	.split("\n")
	.filter(Boolean)
	.flatMap((line) => {
		const [status, sourcePath, destinationPath] = line.split("\t");
		if (status === "A" || status === "M") return [sourcePath];
		if (status.startsWith("R") && status !== "R100") {
			return [destinationPath];
		}
		return [];
	})
	.filter((file) => /^\.changeset\/[^/]+\.md$/.test(file));

const changesetReleases = new Set();
const emptyChangesetFiles = [];
let changedChangesetCount = 0;
for (const file of changedChangesetFiles) {
	let contents;
	try {
		contents = await readFile(resolve(root, file), "utf8");
	} catch {
		continue;
	}
	changedChangesetCount += 1;
	const fileReleases = new Set();
	const frontmatter = contents.match(/^---\s*\n([\s\S]*?)\n---/);
	if (frontmatter) {
		for (const line of frontmatter[1].split("\n")) {
			const match = line.match(
				/^\s*(?:"([^"]+)"|'([^']+)'|([@A-Za-z0-9._/-]+))\s*:\s*([A-Za-z]+)\s*$/,
			);
			if (!match) continue;
			const packageName = match[1] ?? match[2] ?? match[3];
			const bump = match[4];
			if (!releaseBumps.has(bump)) continue;
			fileReleases.add(packageName);
			changesetReleases.add(packageName);
		}
	}
	if (fileReleases.size === 0) emptyChangesetFiles.push(file);
}

if (changedChangesetCount === 0) {
	throw new Error(
		`Changed workspace packages need a changeset added or modified by this branch:\n${[...changedPackages.entries()].map(([path, packageName]) => `- ${path} -> ${packageName}`).join("\n")}`,
	);
}

if (emptyChangesetFiles.length > 0) {
	throw new Error(
		`Empty Changesets cannot accompany release-triggering changes:\n${emptyChangesetFiles.map((file) => `- ${file}`).join("\n")}\nRelease-triggering changes require non-empty bumps:\n${[...changedPackages.entries()].map(([path, packageName]) => `- ${path} -> ${packageName}`).join("\n")}`,
	);
}

const missing = [...changedPackages.entries()]
	.filter(([, packageName]) => !changesetReleases.has(packageName))
	.map(([path, packageName]) => `${path} -> ${packageName}`);

if (missing.length > 0) {
	throw new Error(
		`Changed workspace packages need a changeset naming the same package:\n${missing.map((entry) => `- ${entry}`).join("\n")}`,
	);
}

function getTransitiveConsumers(packageName) {
	let workspace;
	try {
		workspace = workspaceByName(topology, packageName);
	} catch {
		return [];
	}
	return releaseConsumers(topology, workspace.id).map(
		(consumer) => workspaceById(topology, consumer).name,
	);
}

const cascadeRoots = topology.release.bundles.map(
	(bundle) => workspaceById(topology, bundle.workspace).name,
);
const incompleteCascades = cascadeRoots
	.filter((packageName) => changesetReleases.has(packageName))
	.map((packageName) => ({
		packageName,
		missing: getTransitiveConsumers(packageName).filter(
			(consumer) => !changesetReleases.has(consumer),
		),
	}))
	.filter(({ missing }) => missing.length > 0);

if (incompleteCascades.length > 0) {
	throw new Error(
		`Bundled release cascades must include every transitive shipped consumer with at least a patch bump:\n${incompleteCascades
			.map(
				({ packageName, missing }) =>
					`- ${packageName} -> missing ${missing.join(", ")}`,
			)
			.join("\n")}`,
	);
}

const allowedReleases = new Set();
for (const packageName of changedPackages.values()) {
	allowedReleases.add(packageName);
	for (const consumer of getTransitiveConsumers(packageName)) {
		allowedReleases.add(consumer);
	}
}
const unrelatedReleases = [...changesetReleases].filter(
	(packageName) => !allowedReleases.has(packageName),
);
if (unrelatedReleases.length > 0) {
	throw new Error(
		`Changesets must not couple unrelated package releases:\n${unrelatedReleases
			.map((packageName) => `- ${packageName}`)
			.join("\n")}`,
	);
}

console.log(
	`Package changeset coverage passed for ${changedPackages.size} workspace package(s).`,
);

import { fileURLToPath } from "node:url";
import { configDefaults, defineConfig } from "vitest/config";

export default defineConfig({
	resolve: {
		alias: {
			// @cloudflare/workers-oauth-provider imports this Workers runtime
			// module; outside workerd it needs a shim.
			"cloudflare:workers": fileURLToPath(
				new URL("./tests/shims/cloudflare-workers.ts", import.meta.url),
			),
		},
	},
	test: {
		server: {
			deps: {
				// Inline so the `cloudflare:workers` alias above applies to the
				// library's own import of that runtime-only module.
				inline: ["@cloudflare/workers-oauth-provider"],
			},
		},
		exclude: [
			...configDefaults.exclude,
			"tests/nightly/**",
			"tests/cloudflare/**",
		],
		coverage: {
			provider: "v8",
			reportsDirectory: "coverage",
			reporter: ["text", "lcov"],
			exclude: ["tests/performance/**"],
		},
	},
});

import type {
	AuthRequest,
	OAuthHelpers,
} from "@cloudflare/workers-oauth-provider";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { HevyHttpError } from "@hevy-mcp/hevy-client";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import {
	decodeAuthRequest,
	encodeAuthRequest,
	handleAuthorizeGet,
	handleAuthorizePost,
	hasOAuthAccessTokenShape,
	renderAuthorizePage,
	type HevyOAuthDependencies,
} from "./worker-oauth.js";
import { createWorkerFetchHandler } from "./worker.js";

beforeEach(() => {
	vi.stubGlobal("Cloudflare", {
		compatibilityFlags: { global_fetch_strictly_public: true },
	});
});

afterEach(() => {
	vi.unstubAllGlobals();
	vi.restoreAllMocks();
});

function createMockClient(overrides: Partial<HevyClient> = {}): HevyClient {
	return {
		getUserInfo: vi.fn().mockResolvedValue({ data: { id: "user" } }),
		...overrides,
	} as HevyClient;
}

const sampleAuthRequest: AuthRequest = {
	responseType: "code",
	clientId: "client-123",
	redirectUri: "https://claude.ai/api/mcp/auth_callback",
	scope: [],
	state: "state-xyz",
	codeChallenge: "challenge",
	codeChallengeMethod: "S256",
};

type FakeHelpers = Pick<
	OAuthHelpers,
	"parseAuthRequest" | "lookupClient" | "completeAuthorization"
>;

function createFakeHelpers(overrides: Partial<FakeHelpers> = {}): OAuthHelpers {
	const helpers: FakeHelpers = {
		parseAuthRequest: vi.fn().mockResolvedValue(sampleAuthRequest),
		lookupClient: vi.fn().mockResolvedValue({
			clientId: "client-123",
			clientName: "Claude",
			redirectUris: [sampleAuthRequest.redirectUri],
			tokenEndpointAuthMethod: "none",
		}),
		completeAuthorization: vi.fn().mockResolvedValue({
			redirectTo: `${sampleAuthRequest.redirectUri}?code=abc&state=state-xyz`,
		}),
		...overrides,
	};
	return helpers as OAuthHelpers;
}

function createDependencies(
	overrides: Partial<HevyOAuthDependencies<object>> = {},
): HevyOAuthDependencies<object> {
	return {
		validateApiKey: vi.fn().mockResolvedValue("valid"),
		serveMcp: vi.fn().mockResolvedValue(new Response("ok")),
		...overrides,
	};
}

function authorizePostRequest(
	fields: Record<string, string>,
	signal?: AbortSignal,
): Request {
	return new Request("https://worker.example/authorize", {
		method: "POST",
		body: new URLSearchParams(fields),
		signal,
	});
}

describe("OAuth helpers", () => {
	it.each([
		["3f2c8a9e-1b7d-4c6a-9e2f-abc123def456", false],
		["plain-api-key", false],
		["user:grant:secret", true],
		["a:b", false],
		["a:b:c:d", false],
		["::secret", false],
	])("classifies bearer value %j as OAuth token: %j", (token, expected) => {
		expect(hasOAuthAccessTokenShape(token)).toBe(expected);
	});

	it("round-trips an auth request through encode/decode", () => {
		const encoded = encodeAuthRequest(sampleAuthRequest);
		expect(decodeAuthRequest(encoded)).toEqual(sampleAuthRequest);
	});

	it.each([
		["not base64 json", "%%%"],
		["non-object payload", btoa(JSON.stringify("nope"))],
		["missing clientId", btoa(JSON.stringify({ responseType: "code" }))],
		[
			"non-string scope entries",
			btoa(
				JSON.stringify({
					...sampleAuthRequest,
					scope: [42],
				}),
			),
		],
		[
			"missing PKCE code challenge",
			btoa(
				JSON.stringify({
					...sampleAuthRequest,
					codeChallenge: undefined,
				}),
			),
		],
		[
			"plain PKCE method",
			btoa(
				JSON.stringify({
					...sampleAuthRequest,
					codeChallengeMethod: "plain",
				}),
			),
		],
		[
			"implicit flow response type",
			btoa(
				JSON.stringify({
					...sampleAuthRequest,
					responseType: "token",
				}),
			),
		],
	])("rejects tampered auth request payloads: %s", (_label, encoded) => {
		expect(decodeAuthRequest(encoded)).toBeNull();
	});

	it("escapes HTML in the authorization page", () => {
		const page = renderAuthorizePage({
			clientName: '<script>alert("x")</script>',
			encodedRequest: 'abc" onmouseover="evil',
		});
		expect(page).not.toContain("<script>alert");
		expect(page).toContain("&lt;script&gt;");
		expect(page).toContain("abc&quot; onmouseover=&quot;evil");
	});
});

describe("authorize endpoint", () => {
	it("renders the consent form with the client name", async () => {
		const result = await handleAuthorizeGet(
			new Request(
				"https://worker.example/authorize?response_type=code&client_id=client-123",
			),
			createFakeHelpers(),
		);
		expect(result.status).toBe(200);
		expect(result.headers.get("content-type")).toContain("text/html");
		expect(result.headers.get("cache-control")).toBe("no-store");
		expect(result.headers.get("x-frame-options")).toBe("DENY");
		const body = await result.text();
		expect(body).toContain("Claude");
		expect(body).toContain('name="oauth_request"');
		expect(body).toContain('name="hevy_api_key"');
	});

	it("rejects authorization requests without a PKCE challenge", async () => {
		const result = await handleAuthorizeGet(
			new Request(
				"https://worker.example/authorize?response_type=code&client_id=client-123",
			),
			createFakeHelpers({
				parseAuthRequest: vi.fn().mockResolvedValue({
					...sampleAuthRequest,
					codeChallenge: undefined,
				}),
			}),
		);
		expect(result.status).toBe(400);
		expect(await result.text()).toContain("PKCE");
	});

	it("returns a safe 502 when completing authorization fails", async () => {
		const stderrSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		const result = await handleAuthorizePost(
			authorizePostRequest({
				oauth_request: encodeAuthRequest(sampleAuthRequest),
				hevy_api_key: "some-key",
			}),
			{},
			createFakeHelpers({
				completeAuthorization: vi
					.fn()
					.mockRejectedValue(new Error("kv exploded")),
			}),
			createDependencies(),
		);
		expect(result.status).toBe(502);
		expect(await result.text()).toContain("could not be completed");
		const diagnostic = stderrSpy.mock.calls[0]?.[0];
		expect(diagnostic).toMatchObject({
			event: "worker.error",
			context: "oauth-complete-authorization",
		});
		expect(JSON.stringify(diagnostic)).not.toContain("kv exploded");
		stderrSpy.mockRestore();
	});

	it("rejects unknown clients", async () => {
		const result = await handleAuthorizeGet(
			new Request("https://worker.example/authorize?client_id=nope"),
			createFakeHelpers({
				lookupClient: vi.fn().mockResolvedValue(null),
			}),
		);
		expect(result.status).toBe(400);
	});

	it("completes authorization with encrypted-at-rest props", async () => {
		const completeAuthorization = vi.fn().mockResolvedValue({
			redirectTo: `${sampleAuthRequest.redirectUri}?code=abc&state=state-xyz`,
		});
		const validateApiKey = vi.fn().mockResolvedValue("valid");
		const result = await handleAuthorizePost(
			authorizePostRequest({
				oauth_request: encodeAuthRequest(sampleAuthRequest),
				hevy_api_key: " secret-key ",
			}),
			{},
			createFakeHelpers({ completeAuthorization }),
			createDependencies({ validateApiKey }),
		);

		expect(result.status).toBe(302);
		expect(result.headers.get("location")).toContain("code=abc");
		expect(validateApiKey).toHaveBeenCalledWith(
			"secret-key",
			{},
			expect.any(AbortSignal),
			expect.any(Number),
		);
		expect(completeAuthorization).toHaveBeenCalledTimes(1);
		const options = completeAuthorization.mock.calls[0]?.[0];
		expect(options?.request).toEqual(sampleAuthRequest);
		expect(options?.props).toEqual({ hevyApiKey: "secret-key" });
		// SHA-256 of the API key, never the key itself.
		expect(options?.userId).toMatch(/^[0-9a-f]{64}$/);
		expect(options?.userId).not.toContain("secret-key");
	});

	it("re-renders the form when Hevy rejects the API key", async () => {
		const completeAuthorization = vi.fn();
		const result = await handleAuthorizePost(
			authorizePostRequest({
				oauth_request: encodeAuthRequest(sampleAuthRequest),
				hevy_api_key: "bad-key",
			}),
			{},
			createFakeHelpers({ completeAuthorization }),
			createDependencies({
				validateApiKey: vi.fn().mockResolvedValue("invalid"),
			}),
		);
		expect(result.status).toBe(401);
		expect(await result.text()).toContain("rejected this API key");
		expect(completeAuthorization).not.toHaveBeenCalled();
	});

	it("re-renders the form when Hevy validation is unavailable", async () => {
		const result = await handleAuthorizePost(
			authorizePostRequest({
				oauth_request: encodeAuthRequest(sampleAuthRequest),
				hevy_api_key: "some-key",
			}),
			{},
			createFakeHelpers(),
			createDependencies({
				validateApiKey: vi.fn().mockRejectedValue(new Error("upstream outage")),
			}),
		);

		expect(result.status).toBe(502);
		expect(result.headers.get("content-type")).toContain("text/html");
		expect(await result.text()).toContain(
			"Unable to validate the Hevy API key",
		);
	});

	it("re-renders the form when OAuth validation has a configuration error", async () => {
		const result = await handleAuthorizePost(
			authorizePostRequest({
				oauth_request: encodeAuthRequest(sampleAuthRequest),
				hevy_api_key: "some-key",
			}),
			{},
			createFakeHelpers(),
			createDependencies({
				validateApiKey: vi.fn().mockResolvedValue("config-error"),
			}),
		);

		expect(result.status).toBe(500);
		expect(result.headers.get("content-type")).toContain("text/html");
		expect(await result.text()).toContain("Worker configuration error");
	});

	it("rejects submissions without a usable auth request", async () => {
		const completeAuthorization = vi.fn();
		const result = await handleAuthorizePost(
			authorizePostRequest({
				oauth_request: "tampered",
				hevy_api_key: "some-key",
			}),
			{},
			createFakeHelpers({ completeAuthorization }),
			createDependencies(),
		);
