interface MemoryKVEntry {
	value: string;
}

function createMemoryKV() {
	const store = new Map<string, MemoryKVEntry>();
	return {
		store,
		async get(key: string, options?: { type?: string } | string) {
			const entry = store.get(key);
			if (!entry) return null;
			const type = typeof options === "string" ? options : options?.type;
			return type === "json" ? JSON.parse(entry.value) : entry.value;
		},
		async put(key: string, value: string) {
			store.set(key, { value });
		},
		async delete(key: string) {
			store.delete(key);
		},
		async list(options?: { prefix?: string }) {
			const prefix = options?.prefix ?? "";
			return {
				keys: [...store.keys()]
					.filter((name) => name.startsWith(prefix))
					.map((name) => ({ name })),
				list_complete: true,
			};
		},
	};
}

function base64UrlEncode(bytes: Uint8Array): string {
	let binary = "";
	for (const byte of bytes) binary += String.fromCharCode(byte);
	return btoa(binary)
		.replaceAll("+", "-")
		.replaceAll("/", "_")
		.replace(/=+$/, "");
}

const initializeBody = {
	jsonrpc: "2.0",
	id: 1,
	method: "initialize",
	params: {
		protocolVersion: "2025-11-25",
		capabilities: {},
		clientInfo: { name: "oauth-test", version: "1" },
	},
};

async function parseMcpResponse(response: Response) {
	const text = await response.text();
	if (response.headers.get("content-type")?.includes("text/event-stream")) {
		const data = text
			.split("\n")
			.find((line) => line.startsWith("data: "))
			?.slice(6);
		if (!data) throw new Error(`Missing SSE data: ${text}`);
		return JSON.parse(data) as Record<string, unknown>;
	}
	return JSON.parse(text) as Record<string, unknown>;
}

